import json

WEATHER = {
    "paris": {"temp": 18, "sky": "cloudy"},
    "cairo": {"temp": 35, "sky": "sunny"},
}

def server(path):
    city = path.split("/")[-1]
    if city in WEATHER:
        body = {"city": city, **WEATHER[city]}
        return 200, json.dumps(body)
    return 404, json.dumps({"error": "city not found"})

def client(city):
    status, text = server("/weather/" + city)
    data = json.loads(text)
    if status == 200:
        print(city, "is", data["temp"], "degrees and", data["sky"])
    else:
        print("Oops:", data["error"])
    show(data, "reply for " + city)

client("paris")
client("cairo")
client("mars")

