def tip(bill, percent):
    amount = bill * percent / 100
    return amount


def total(bill, percent):
    return bill + tip(bill, percent)


dinner = tip(40, 15)
print("Dinner tip:", dinner)

print("Pizza tip:", tip(20, 10))
print("Pizza total:", total(20, 10))

show({
    "dinner tip": dinner,
    "pizza tip": tip(20, 10),
    "pizza total": total(20, 10),
}, "Tip machine results")

