secret = "pizza"

def guard(guess):
    if guess == secret:
        return "Welcome in!"
    elif len(guess) == 0:
        return "You didn't say anything."
    else:
        return "Wrong word. Door stays shut."

guesses = ["pizza", "", "cake"]
results = {}

for g in guesses:
    answer = guard(g)
    results[repr(g)] = answer
    print(repr(g), "->", answer)

show(results, "What the guard said")

