menu = {"/": "Welcome!", "/pizza": "Here is a hot pizza"}

def server(path):
    if path == "/crash":
        return 500, "Our kitchen broke!"
    if path in menu:
        return 200, menu[path]
    return 404, "We don't have that"

results = {}
for ask in ["/", "/pizza", "/tacos", "/crash"]:
    code, body = server(ask)
    print(ask, "->", code, body)
    results[ask] = code

show(results, "what the server said")

