users = [
    {"id": 1, "name": "Mia", "pet": "cat"},
    {"id": 2, "name": "Leo", "pet": "dog"},
    {"id": 3, "name": "Zoe", "pet": "fish"},
    {"id": 4, "name": "Sam", "pet": "cat"},
]
show([[r["id"], r["name"], r["pet"]] for r in users], "the table")

index = {}
for position, row in enumerate(users):
    index[row["name"]] = position
show(index, "the index")

def find_slow(name):
    for row in users:
        if row["name"] == name:
            return row

def find_fast(name):
    position = index[name]
    return users[position]

print(find_slow("Zoe"))
print(find_fast("Zoe"))

