import random

story = "the cat sat on the mat . the cat ate the fish . the dog sat on the rug ."
words = story.split()

follows = {}
for i in range(len(words) - 1):
    now, nxt = words[i], words[i + 1]
    follows.setdefault(now, []).append(nxt)

show(follows, "who follows who")

def predict(word):
    return random.choice(follows[word])

sentence = ["the"]
for _ in range(7):
    sentence.append(predict(sentence[-1]))
print(" ".join(sentence))
